import React, { useState } from "react";
import { auth, database } from "../compornents/firebaseConfig";
import { ref, push, set, serverTimestamp } from "firebase/database";

const Dashboard = () => {
  const [itemName, setItemName] = useState("");
  const [location, setLocation] = useState("");
  const [issueTitle, setIssueTitle] = useState("");
  const [description, setDescription] = useState("");

  const submitReport = async (e) => {
    e.preventDefault();

    if (!auth.currentUser) {
      alert("You must be logged in to submit a report");
      return;
    }

    const reporterUid = auth.currentUser.uid;
    const reporterName = auth.currentUser.displayName || "Anonymous";

    try {
      // Create a new breakdown reference with unique id
      const newBreakdownRef = push(ref(database, "breakdowns"));
      await set(newBreakdownRef, {
        reporterUid: reporterUid,
        reporterName: reporterName,
        message: `${issueTitle}: ${description}`,
        itemName: itemName,
        location: location,
        status: "pending",
        assignedTechnician: null,
        fixDetails: null,
        timestamps: {
          created: serverTimestamp(),
          updated: serverTimestamp(),
        },
      });

      alert("Report submitted successfully!");
      // reset form
      setItemName("");
      setLocation("");
      setIssueTitle("");
      setDescription("");
    } catch (error) {
      alert("Error submitting report: " + error.message);
    }
  };

  return (
    <form onSubmit={submitReport} className="space-y-6">
      <label>
        Item Name
        <input
          value={itemName}
          onChange={(e) => setItemName(e.target.value)}
          placeholder="e.g., Printer"
          className="form-input w-full"
        />
      </label>

      <label>
        Location
        <select
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          className="form-select w-full"
        >
          <option>Room 1</option>
          <option>Room 2</option>
          <option>Room 3</option>
          <option>Room 4</option>
          <option>Room 5</option>
        </select>
      </label>

      <label>
        Issue Title
        <input
          value={issueTitle}
          onChange={(e) => setIssueTitle(e.target.value)}
          placeholder="e.g., Printer not working"
          className="form-input w-full"
        />
      </label>

      <label>
        Description
        <textarea
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Detailed description..."
          className="form-textarea w-full"
        />
      </label>

      <button
        type="submit"
        className="bg-green-600 text-white px-6 py-2 rounded-lg"
      >
        Submit Report
      </button>
    </form>
  );
};

export default Dashboard;
